using System;using System.IO;using System.Reflection;using System.Drawing;using System.Drawing.Drawing2D;using System.Drawing.Imaging;using JouchoPet;
class ArcheryEffectsCheck {
 static int checks;static readonly string Folder=Path.Combine("qa","v0646");
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static Bitmap Image(Action<Graphics> draw){var b=new Bitmap(1200,1000,PixelFormat.Format32bppPArgb);using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;draw(g);}return b;}
 static int Outside(Bitmap image,RectangleF bounds){int count=0;int[] pixels=PoseMesh.Read(image);for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++)if((uint)pixels[y*image.Width+x]>>24>0&&!bounds.Contains(x+.5f,y+.5f))count++;return count;}
 static long Difference(Bitmap a,Bitmap b){int[] pa=PoseMesh.Read(a),pb=PoseMesh.Read(b);long count=0;for(int i=0;i<pa.Length;i++)if(pa[i]!=pb[i])count++;return count;}
 static int Visible(Bitmap b){int count=0;foreach(int p in PoseMesh.Read(b))if((uint)p>>24>8)count++;return count;}
 static int[] RawPixels(Bitmap image){var pixels=new int[image.Width*image.Height];var data=image.LockBits(new Rectangle(0,0,image.Width,image.Height),ImageLockMode.ReadOnly,PixelFormat.Format32bppPArgb);try{for(int y=0;y<image.Height;y++)System.Runtime.InteropServices.Marshal.Copy(IntPtr.Add(data.Scan0,y*data.Stride),pixels,y*image.Width,image.Width);}finally{image.UnlockBits(data);}return pixels;}
 static int LocalAlpha(Bitmap image,PointF point){return LocalAlpha(PoseMesh.Read(image),image.Width,image.Height,point);} static int LocalAlpha(int[] pixels,int width,int height,PointF point){int alpha=0;for(int y=Math.Max(0,(int)point.Y-2);y<=Math.Min(height-1,(int)point.Y+2);y++)for(int x=Math.Max(0,(int)point.X-2);x<=Math.Min(width-1,(int)point.X+2);x++)alpha=Math.Max(alpha,(int)((uint)pixels[y*width+x]>>24));return alpha;}
 static double GoldTone(Bitmap image){double sum=0;int count=0;foreach(uint p in Array.ConvertAll(PoseMesh.Read(image),v=>(uint)v)){double alpha=p>>24;if(alpha<40)continue;sum+=((int)(p>>8&255)-(int)(p&255))*255/alpha;count++;}return count==0?0:sum/count;}
 static Bitmap ArrowTexture(PointF tip,PointF axis,double length,PointF translate){return Image(g=>{g.TranslateTransform(translate.X,translate.Y);PaintedArrowArt.Draw(g,tip,axis,length);});}
 static double MeanVisibleAlpha(Bitmap b){double sum=0;int count=0;foreach(uint p in Array.ConvertAll(RawPixels(b),v=>(uint)v))if(p>>24>8){sum+=p>>24;count++;}return sum/Math.Max(1,count);}
 static void ValidAlpha(Bitmap b,string label){foreach(uint p in Array.ConvertAll(RawPixels(b),v=>(uint)v)){uint a=p>>24;if((p>>16&255)>a||(p>>8&255)>a||(p&255)>a)throw new Exception("invalid premultiplied alpha / "+label);}}
 static void Extent(Action<Graphics> draw,RectangleF bounds,string label){const int pad=64;int left=(int)Math.Floor(bounds.Left)-pad,top=(int)Math.Floor(bounds.Top)-pad,w=(int)Math.Ceiling(bounds.Right)-left+pad,h=(int)Math.Ceiling(bounds.Bottom)-top+pad;
  using(var b=new Bitmap(w,h,PixelFormat.Format32bppPArgb)){using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform(-left,-top);draw(g);}RectangleF local=bounds;local.Offset(-left,-top);if(Outside(b,local)>0)throw new Exception("effect extends outside declared overlay / "+label);ValidAlpha(b,label);}
 }
 static void ArrowTextureAndHelix(){PaintedBowArt.Prepare();PaintedArrowArt.Prepare();Check(PaintedArrowArt.DecodeCount==1,"arrow artwork is decoded once by the startup artwork preparation path");
  var old=Assembly.LoadFile(Path.GetFullPath("dist/IsekaijouchoPet-v0.6.42-preview/IsekaijouchoPet.exe"));var flags=BindingFlags.Static|BindingFlags.NonPublic;var oldArt=old.GetType("JouchoPet.ArcheryArt");var oldPoint=oldArt.GetMethod("HelixPoint",flags);var oldSpiral=oldArt.GetMethod("Spiral",flags);
  foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){PointF axis=ArcheryMotion.Axis(facing),tip=new PointF(facing<0?425.25f:800.25f,400.75f),across=new PointF(-axis.Y,axis.X);double length=ArcheryMotion.ArrowLength(size);
   using(var b=ArrowTexture(tip,axis,length,PointF.Empty))using(var negative=ArrowTexture(RigParts.Add(tip,-1100,-850),axis,length,new PointF(1100,850)))using(var positive=ArrowTexture(RigParts.Add(tip,900,700),axis,length,new PointF(-900,-700))){double error=Math.Max(PixelError(b,negative),PixelError(b,positive));Check(error<.015,"painted arrow mapping works in both views with positive and negative desktop origins / "+size+" / "+facing);ValidAlpha(b,"arrow texture");var colors=new System.Collections.Generic.HashSet<int>();int solid=0,warm=0;foreach(uint p in Array.ConvertAll(RawPixels(b),v=>(uint)v))if(p>>24>220){solid++;colors.Add((int)(p&0xffffff));if((p>>16&255)>=(p>>8&255)&&(p>>8&255)>=(p&255))warm++;}Check(solid>70&&colors.Count>30&&warm>solid*.8,"rendered arrow preserves painted ivory/gold material detail rather than a flat vector stroke / "+size+" / "+facing);Check(LocalAlpha(b,tip)>35&&LocalAlpha(b,RigParts.Add(tip,-axis.X*length,-axis.Y*length))>35,"painted arrowhead and open nock stay registered to their animation anchors / "+size+" / "+facing);Check(Outside(b,PaintedArrowArt.Bounds(tip,axis,length))==0,"all painted feather and glow pixels fit the texture bounds / "+size+" / "+facing);}
   PointF start=ArcheryArt.HelixPoint(tip,axis,length,size,.123,0),end=ArcheryArt.HelixPoint(tip,axis,length,size,.123,1);Check(RigParts.Length(start,tip)<.001&&RigParts.Length(end,RigParts.Add(tip,-axis.X*length*2,-axis.Y*length*2))<.001,"helix spans arrowhead to one arrow length behind nock, exactly two lengths total / "+size+" / "+facing);
   double maxRadius=0;int crossings=0;double previous=0;for(int i=1;i<1800;i++){double t=i/1800.0;PointF p=ArcheryArt.HelixPoint(tip,axis,length,size,.123,t);double lateral=(p.X-tip.X)*across.X+(p.Y-tip.Y)*across.Y;maxRadius=Math.Max(maxRadius,Math.Abs(lateral));if(Math.Abs(lateral)>.001){if(previous*lateral<0)crossings++;previous=lateral;}}Console.WriteLine("Helix crossings="+crossings+" max radial error="+Math.Abs(maxRadius-size*.056).ToString("F6"));Check(crossings==12&&Math.Abs(maxRadius-size*.056)<size*.056*(1-Math.Cos(Math.PI*12/3600))+.0001,"helix keeps six full turns and the enlarged radius along its full span / "+size+" / "+facing);
   double crestAge=2.5*Math.PI/17;PointF middle=ArcheryArt.HelixPoint(tip,axis,length,size,crestAge,.25),priorMiddle=(PointF)oldPoint.Invoke(null,new object[]{tip,axis,length,(double)size,crestAge,.5});double currentSide=Math.Abs((middle.X-tip.X)*across.X+(middle.Y-tip.Y)*across.Y),priorSide=Math.Abs((priorMiddle.X-tip.X)*across.X+(priorMiddle.Y-tip.Y)*across.Y);Check(Math.Abs(currentSide/priorSide-2)<.0001&&ArcheryArt.HelixRadius(size,0)==0&&ArcheryArt.HelixRadius(size,1)==0,"radius is truly twice0.6.42 around the arrow midpoint and tapers to zero at both ends / "+size+" / "+facing);
   PointF phaseA=ArcheryArt.HelixPoint(tip,axis,length,size,.1,.25),phaseB=ArcheryArt.HelixPoint(tip,axis,length,size,.13,.25),period=ArcheryArt.HelixPoint(tip,axis,length,size,.1+Math.PI*2/17,.25);Check(RigParts.Length(phaseA,phaseB)>size*.005&&RigParts.Length(phaseA,period)<.001,"helix continuously rotates about a stationary arrow and closes each rotation smoothly / "+size+" / "+facing);
   foreach(bool back in new[]{false,true})using(var b=Image(g=>ArcheryArt.Spiral(g,tip,axis,length,size,.123,back)))using(var prior=Image(g=>oldSpiral.Invoke(null,new object[]{g,tip,axis,length,(double)size,.123,back}))){ValidAlpha(b,"helix layer");double ratio=MeanVisibleAlpha(b)/MeanVisibleAlpha(prior);Console.WriteLine("Helix raster mean opacity ratio="+ratio.ToString("F3")+" / "+size+" / "+facing+" / back="+back);Check(ArcheryArt.HelixOpacityFactor==1&&ratio>.7&&ratio<1.5&&Visible(b)>150,"both depth layers visibly use doubled-opacity ink versus 0.6.44 while preserving their thicker stroke / "+size+" / "+facing+" / "+back);}
  }
  Check(PaintedArrowArt.DecodeCount==1,"all sizes, directions and world origins reuse the prepared arrow texture");
 }
 static void BowStyle(){var old=Assembly.LoadFile(Path.GetFullPath("dist/IsekaijouchoPet-v0.6.40-preview/IsekaijouchoPet.exe"));var oldArt=old.GetType("JouchoPet.ArcheryArt");var flags=BindingFlags.Static|BindingFlags.NonPublic;var oldAt=old.GetType("JouchoPet.ArcheryMotion").GetMethod("At",flags);var oldParticles=oldArt.GetMethod("BowParticles",flags);int size=300,width=347;PointF grip=new PointF(550,440),axis=ArcheryMotion.Axis(1);foreach(double age in new[]{1.7,2.3,3.1}){object oldPose=oldAt.Invoke(null,new object[]{age,1});var pose=ArcheryMotion.At(Math.Min(age,2.2),1);using(var prior=Image(g=>oldParticles.Invoke(null,new object[]{g,grip,axis,(double)size,oldPose})))using(var current=Image(g=>ArcheryArt.BowParticles(g,grip,axis,size,pose))){double ratio=Visible(current)/(double)Visible(prior),oldGold=GoldTone(prior),newGold=GoldTone(current);Console.WriteLine("Bow particle visible-area ratio="+ratio.ToString("F2")+"; gold chroma old="+oldGold.ToString("F1")+", new="+newGold.ToString("F1"));Check(ratio>2.3,"bow particle density visibly exceeds released0.6.40 / "+age);Check(newGold>oldGold+30,"bow particle hue is distinctly more pale-golden / "+age);}}
  foreach(int facing in new[]{-1,1}){axis=ArcheryMotion.Axis(facing);double min=double.MaxValue,max=0;for(int i=1;i<10;i++){PointF a=ArcheryArt.BowCurve(grip,axis,size,(i-.7)/10),b=ArcheryArt.BowCurve(grip,axis,size,i/10.0),c=ArcheryArt.BowCurve(grip,axis,size,(i+.7)/10);double cross=Math.Abs((b.X-a.X)*(c.Y-a.Y)-(b.Y-a.Y)*(c.X-a.X)),radius=RigParts.Length(a,b)*RigParts.Length(b,c)*RigParts.Length(c,a)/(2*cross);min=Math.Min(min,radius);max=Math.Max(max,radius);}Check(max/min<1.005,"rest bow curvature stays evenly round from tip to grip / "+facing);}
  using(var sheet=new Bitmap(1200,850))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(46,54,66));g.SmoothingMode=SmoothingMode.AntiAlias;double[] ages={1.7,2.3,3.1};for(int i=0;i<3;i++){int x=i*400;var pose=ArcheryMotion.At(ages[i],1);PointF origin=new PointF(x+15,140);oldArt.GetMethod("Bow",flags).Invoke(null,new object[]{g,origin,width,(double)size,oldAt.Invoke(null,new object[]{ages[i],1})});ArcheryArt.Bow(g,new PointF(x+15,565),width,size,pose);g.DrawString("0.6.40 / "+ages[i].ToString("F1"),SystemFonts.DefaultFont,Brushes.White,x+15,15);g.DrawString("0.6.43 / 25 degree painted ivory bow and cord",SystemFonts.DefaultFont,Brushes.White,x+15,440);}sheet.Save(Path.Combine(Folder,"bow-style-comparison.png"),ImageFormat.Png);}Check(true,"rounder bow and increased pale-gold particle comparison saved");
 }
 static void Conjuration(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;Point origin=new Point(440-width/2,430);PointF grip=RigParts.Add(ArcheryMotion.Grip(width,size,facing),origin.X,origin.Y),axis=ArcheryMotion.Axis(facing);ArcheryPose before=ArcheryMotion.At(.14,facing),gather=ArcheryMotion.At(.55,facing),arrive=ArcheryMotion.At(ArcheryMotion.BowAppearAt,facing);using(var b=Image(g=>ArcheryArt.Bow(g,origin,width,size,before)))Check(!ArcheryArt.HasBowEffect(before)&&Visible(b)==0,"no conjuration before lifting starts / "+size+" / "+facing);using(var b=Image(g=>ArcheryArt.Bow(g,origin,width,size,gather)))Check(gather.Ready>0&&gather.Ready<1&&gather.Bow==0&&ArcheryArt.HasBowEffect(gather)&&Visible(b)>100,"star cloud and arm lift play together before full bow appears / "+size+" / "+facing);
