 [STAThread]static void Main(string[] args){try{Directory.CreateDirectory(Folder);if(args.Length>0){if(args[0]=="--performance-only"){Performance();ProjectilePerformance();}else if(args[0]=="--color-probe")RenderingColors();else if(args[0]=="--arrow-check"){ArrowTextureAndHelix();Appearance();Preview();RenderingColors();}else if(args[0]=="--texture-check"){RasterArtwork();RasterMapping();BowLoad();Conjuration();Bounds();Preview();RenderingColors();}else throw new Exception("Unknown check mode");Console.WriteLine("All "+checks+" selected effect checks passed.");return;}Geometry();RasterArtwork();RasterMapping();ArrowTextureAndHelix();BowStyle();BowLoad();Conjuration();FormationSampling();Bounds();Appearance();Preview();RenderingColors();Performance();ProjectilePerformance();Console.WriteLine("All "+checks+" effect checks passed.");}catch(Exception e){Console.WriteLine(e);Environment.ExitCode=1;}}
 static void RasterArtwork(){foreach(string name in new[]{"v0642/ivory-bow.png","v0642/ivory-bowstring.png","v0643/ivory-arrow.png"})using(var source=AssetStore.Image(name)){int transparent=0,soft=0,solid=0,warm=0;var colors=new System.Collections.Generic.HashSet<int>();foreach(int pixel in RawPixels(source)){uint p=(uint)pixel;int a=(int)(p>>24);if(a==0)transparent++;else if(a<245)soft++;else{solid++;int r=(int)(p>>16&255),green=(int)(p>>8&255),b=(int)(p&255);if(r>=green&&green>=b)warm++;colors.Add(pixel&0xffffff);}}Check(transparent>source.Width*source.Height*.3&&soft>1000&&solid>1000,"painted source has true transparent background, soft edges and solid body / "+name);Check(colors.Count>100&&warm>solid*.8,"painted source preserves varied ivory and gold material shading / "+name);}}
 static Bitmap Texture(PointF origin,int width,int size,ArcheryPose pose,PointF translate){return Image(g=>{g.TranslateTransform(translate.X,translate.Y);PointF axis=ArcheryMotion.Axis(pose.Facing),grip=RigParts.Add(ArcheryMotion.Grip(width,size,pose.Facing),origin.X,origin.Y),nock=RigParts.Add(ArcheryMotion.Nock(width,size,pose),origin.X,origin.Y);PaintedBowArt.Draw(g,grip,axis,nock,size,ArcheryArt.BowFlex(pose),pose.Bow);});}
 static long AlphaMass(Bitmap image){long sum=0;foreach(uint p in Array.ConvertAll(RawPixels(image),v=>(uint)v))sum+=p>>24;return sum;}
 static double PixelError(Bitmap a,Bitmap b){int[] ap=RawPixels(a),bp=RawPixels(b);long error=0,total=0;for(int i=0;i<ap.Length;i++)for(int channel=0;channel<4;channel++){int av=(ap[i]>>(channel*8))&255,bv=(bp[i]>>(channel*8))&255;error+=Math.Abs(av-bv);total+=Math.Max(av,bv);}return error/(double)Math.Max(1,total);}
 static void RasterMapping(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;PointF origin=new PointF(400.25f,310.75f),axis=ArcheryMotion.Axis(facing),grip=RigParts.Add(ArcheryMotion.Grip(width,size,facing),origin.X,origin.Y);double transformError=0;foreach(double age in new[]{2.0,2.65,3.15,3.715}){var pose=ArcheryMotion.At(age,facing);pose.Arrow=0;using(var baseline=Texture(origin,width,size,pose,PointF.Empty))using(var negative=Texture(new PointF(origin.X-800,origin.Y-650),width,size,pose,new PointF(800,650)))using(var positive=Texture(new PointF(origin.X+700,origin.Y+550),width,size,pose,new PointF(-700,-550))){transformError=Math.Max(transformError,Math.Max(PixelError(baseline,negative),PixelError(baseline,positive)));}}Console.WriteLine("Texture translated-origin relative pixel error="+transformError.ToString("F6")+" / "+size+" / "+facing);Check(transformError<.015,"painted bow respects nonzero and negative world origin with graphics translation / "+size+" / "+facing);
   int missing=0;double lowerMass=0,lastMass=-1;var full=ArcheryMotion.At(ArcheryMotion.FullDrawAt,facing);full.Arrow=0;PointF nock=RigParts.Add(ArcheryMotion.Nock(width,size,full),origin.X,origin.Y);using(var b=Texture(origin,width,size,full,PointF.Empty)){int[] pixels=PoseMesh.Read(b);foreach(double end in new[]{0.0,1.0}){PointF tip=ArcheryArt.BowCurve(grip,axis,size,end,ArcheryArt.BowFlex(full));for(int i=0;i<=120;i++){PointF point=RigParts.Mix(tip,nock,i/120.0);if(LocalAlpha(pixels,b.Width,b.Height,point)<20)missing++;}}Check(missing==0,"painted string has no gaps at tips, nock or either tensioned segment / "+size+" / "+facing);var colors=new System.Collections.Generic.HashSet<int>();foreach(uint p in Array.ConvertAll(PoseMesh.Read(b),v=>(uint)v))if(p>>24>240)colors.Add((int)(p&0xffffff));Check(colors.Count>30,"rendered bow retains material color variation at pet resolution / "+size+" / "+facing);lowerMass=AlphaMass(b);}
   foreach(double opacity in new[]{0.0,.1,.2,.4,.6,.8,1.0}){var pose=full;pose.Bow=opacity;using(var b=Texture(origin,width,size,pose,PointF.Empty)){double mass=AlphaMass(b);if(opacity==0&&mass!=0)throw new Exception("painted bow remains visible at zero opacity");if(mass<lastMass)throw new Exception("painted bow opacity is not monotonic");if(Math.Abs(mass/lowerMass-opacity)>.012)throw new Exception("painted bow opacity is nonlinear: "+mass/lowerMass+" vs "+opacity);lastMass=mass;}}Check(true,"painted bow alpha fades linearly and clears completely without shrinking / "+size+" / "+facing);
   double epsilonError=0;foreach(double age in new[]{2.0,2.2,3.15,3.55,3.69,3.92})using(var a=Texture(origin,width,size,ArcheryMotion.At(age-1e-6,facing),PointF.Empty))using(var b=Texture(origin,width,size,ArcheryMotion.At(age+1e-6,facing),PointF.Empty))epsilonError=Math.Max(epsilonError,PixelError(a,b));Check(epsilonError<.003,"painted bow deformation and recovery join continuously / "+size+" / "+facing);
  }
  using(var sheet=new Bitmap(1200,1000))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(46,54,66));g.SmoothingMode=SmoothingMode.AntiAlias;foreach(int facing in new[]{-1,1})for(int i=0;i<3;i++){int x=i*400,y=facing<0?0:500;var pose=ArcheryMotion.At(new[]{2.0,3.15,3.715}[i],facing);PointF origin=new PointF(x+20,y+180),axis=ArcheryMotion.Axis(facing),grip=RigParts.Add(ArcheryMotion.Grip(347,300,facing),origin.X,origin.Y),nock=RigParts.Add(ArcheryMotion.Nock(347,300,pose),origin.X,origin.Y);PaintedBowArt.Draw(g,grip,axis,nock,300,ArcheryArt.BowFlex(pose),1);g.DrawString((facing<0?"LEFT":"RIGHT")+" / ivory artwork / "+pose.Age.ToString("F3"),SystemFonts.DefaultFont,Brushes.White,x+15,y+15);}sheet.Save(Path.Combine(Folder,"painted-bow-contact.png"),ImageFormat.Png);}Check(true,"independent painted bow and cord contact sheet saved");
 }
 static void Performance(){using(var image=new Bitmap(900,650,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;for(int frame=0;frame<12;frame++)ArcheryArt.Bow(g,new PointF(250,220),width,size,ArcheryMotion.At(2+frame/60.0,facing));var watch=System.Diagnostics.Stopwatch.StartNew();const int frames=180;for(int frame=0;frame<frames;frame++){g.Clear(Color.Transparent);ArcheryArt.Bow(g,new PointF(250,220),width,size,ArcheryMotion.At(2+(frame%120)/60.0,facing));}watch.Stop();double ms=watch.Elapsed.TotalMilliseconds/frames;Console.WriteLine("Warm bow overlay mean ms="+ms.ToString("F3")+" / "+size+" / "+facing+" / changing draw and rebound");Check(ms<12,"painted bow overlay stays below12ms per changing frame / "+size+" / "+facing);}}}
 static void RenderingColors(){using(var image=new Bitmap(900,650,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(image)){g.Clear(Color.Transparent);g.SmoothingMode=SmoothingMode.AntiAlias;ArcheryArt.Bow(g,new Point(200,150),347,300,ArcheryMotion.At(2.2,1));var arrow=new MagicArrow(new PointF(700,160),1,new Rectangle(0,0,900,650),300);arrow.Update(.1);ArcheryArt.Projectile(g,arrow);int visible=0,invalid=0,alphaOvershoot=0,greenAboveRed=0,blueAboveGreen=0,maxGR=0,maxBG=0;double warmBias=0;int[] pixels=RawPixels(image);for(int i=0;i<pixels.Length;i++){uint p=(uint)pixels[i];int a=(int)(p>>24),r=(int)(p>>16&255),green=(int)(p>>8&255),b=(int)(p&255);if(a==0&&p!=0)invalid++;if(r>a||green>a||b>a){invalid++;alphaOvershoot=Math.Max(alphaOvershoot,Math.Max(r,Math.Max(green,b))-a);}if(a<12)continue;visible++;warmBias+=green-b;if(green>r){greenAboveRed++;maxGR=Math.Max(maxGR,green-r);if(greenAboveRed<4)Console.WriteLine("Green>red at "+i%image.Width+","+i/image.Width+": A/R/G/B="+a+"/"+r+"/"+green+"/"+b);}if(b>green){blueAboveGreen++;maxBG=Math.Max(maxBG,b-green);if(blueAboveGreen<4)Console.WriteLine("Blue>green at "+i%image.Width+","+i/image.Width+": A/R/G/B="+a+"/"+r+"/"+green+"/"+b);}}Console.WriteLine("Effect colors: visible="+visible+" invalidPArgb="+invalid+" maxChannelAboveAlpha="+alphaOvershoot+" greenAboveRed="+greenAboveRed+" maxG-R="+maxGR+" blueAboveGreen="+blueAboveGreen+" maxB-G="+maxBG+" meanG-B="+(warmBias/Math.Max(1,visible)).ToString("F3"));Check(invalid==0,"raster and procedural effects preserve strict valid premultiplied alpha");}}
 static void ProjectilePerformance(){PaintedArrowArt.Prepare();using(var image=new Bitmap(1400,900,PixelFormat.Format32bppPArgb))using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){const int frames=180;var samples=new MagicArrow[frames];for(int frame=0;frame<frames;frame++){samples[frame]=new MagicArrow(new PointF(facing>0?800:400,260),facing,new Rectangle(-1000,-1000,4000,3000),size);samples[frame].Update(.15+(frame%60)/600.0);}for(int frame=0;frame<12;frame++)ArcheryArt.Projectile(g,samples[frame]);var watch=System.Diagnostics.Stopwatch.StartNew();for(int frame=0;frame<frames;frame++){g.Clear(Color.Transparent);ArcheryArt.Projectile(g,samples[frame]);}watch.Stop();double ms=watch.Elapsed.TotalMilliseconds/frames;Console.WriteLine("Warm painted-arrow + full2L-helix + release-ripple mean ms="+ms.ToString("F3")+" / "+size+" / "+facing);Check(ms<8,"complete painted projectile overlay stays below8ms per changing frame / "+size+" / "+facing);}}Check(PaintedArrowArt.DecodeCount==1,"repeated complete projectile frames never decode the PNG again");}
 static void BowLoad(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;Point origin=new Point(440-width/2,430);PointF grip=RigParts.Add(ArcheryMotion.Grip(width,size,facing),origin.X,origin.Y),axis=ArcheryMotion.Axis(facing);PointF restTop=ArcheryArt.BowCurve(grip,axis,size,0),restBottom=ArcheryArt.BowCurve(grip,axis,size,1),loadedTop=ArcheryArt.BowCurve(grip,axis,size,0,1),loadedBottom=ArcheryArt.BowCurve(grip,axis,size,1,1);foreach(double age in new[]{2.0,2.5,3.15,3.55,3.62,3.69,3.715,3.765,3.9,4.1})if(RigParts.Length(grip,ArcheryArt.BowCurve(grip,axis,size,.5,ArcheryArt.BowFlex(ArcheryMotion.At(age,facing))))>.0001)throw new Exception("bow grip shifted under load");Check(true,"grip fixed through draw, release, and vibration / "+size+" / "+facing);
   double backward=(restTop.X-loadedTop.X)*axis.X+(restTop.Y-loadedTop.Y)*axis.Y,restSpan=RigParts.Length(restTop,restBottom),loadedSpan=RigParts.Length(loadedTop,loadedBottom);Check(Math.Abs(backward-size*.025)<.0001&&Math.Abs(restSpan-loadedSpan-size*.012)<.0001,"limbs bend backward and slightly inward without whole-bow scaling / "+size+" / "+facing);
   var full=ArcheryMotion.At(ArcheryMotion.FullDrawAt,facing);PointF nock=RigParts.Add(ArcheryMotion.Nock(width,size,full),origin.X,origin.Y);double tipDepth=(grip.X-loadedTop.X)*axis.X+(grip.Y-loadedTop.Y)*axis.Y,nockDepth=(grip.X-nock.X)*axis.X+(grip.Y-nock.Y)*axis.Y;Check(nockDepth>tipDepth+size*.02,"full draw visibly tensions string behind bent limb tips / "+size+" / "+facing);double loadedString=RigParts.Length(loadedTop,nock)+RigParts.Length(loadedBottom,nock);Check(Math.Abs(loadedString/restSpan-1)<.035,"drawn string length stays within3.5percent of resting span / "+size+" / "+facing);
   using(var image=Image(g=>ArcheryArt.Bow(g,origin,width,size,full))){Console.WriteLine("Loaded bow alpha top/bottom/stringTop/stringBottom="+LocalAlpha(image,loadedTop)+"/"+LocalAlpha(image,loadedBottom)+"/"+LocalAlpha(image,RigParts.Mix(loadedTop,nock,.5))+"/"+LocalAlpha(image,RigParts.Mix(loadedBottom,nock,.5)));Check(LocalAlpha(image,loadedTop)>127&&LocalAlpha(image,loadedBottom)>127&&LocalAlpha(image,ArcheryArt.BowCurve(grip,axis,size,.015,1))>200&&LocalAlpha(image,ArcheryArt.BowCurve(grip,axis,size,.985,1))>200&&LocalAlpha(image,RigParts.Mix(loadedTop,nock,.5))>90&&LocalAlpha(image,RigParts.Mix(loadedBottom,nock,.5))>90,"string remains visibly attached to both flexed limb endpoints / "+size+" / "+facing);}
  }
  Check(Math.Abs(ArcheryArt.BowFlex(ArcheryMotion.At(ArcheryMotion.ReleaseAt,1))-1)<1e-9&&Math.Abs(ArcheryArt.BowFlex(ArcheryMotion.At(ArcheryMotion.ReleaseAt+.14,1)))<1e-9,"bow unloads with string within140ms of release");double minimum=0,maximum=0;for(int i=0;i<=230;i++){double flex=ArcheryArt.BowFlex(ArcheryMotion.At(ArcheryMotion.ReleaseAt+.14+i/1000.0,1));minimum=Math.Min(minimum,flex);maximum=Math.Max(maximum,flex);}Check(minimum<-.04&&maximum>.04&&Math.Max(-minimum,maximum)<.14&&ArcheryArt.BowFlex(ArcheryMotion.At(ArcheryMotion.ReleaseAt+.38,1))==0,"brief small alternating limb vibration decays completely");foreach(double age in new[]{ArcheryMotion.ReleaseAt,ArcheryMotion.ReleaseAt+.14,ArcheryMotion.ReleaseAt+.30,ArcheryMotion.ReleaseAt+.37})if(Math.Abs(ArcheryArt.BowFlex(ArcheryMotion.At(age-1e-6,1))-ArcheryArt.BowFlex(ArcheryMotion.At(age+1e-6,1)))>1e-4)throw new Exception("bow rebound discontinuity");Check(true,"release and residual vibration join continuously");
  using(var sheet=new Bitmap(1600,800))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(46,54,66));g.SmoothingMode=SmoothingMode.AntiAlias;double[] ages={2.0,2.65,3.15,3.55,3.62,3.69,3.715,3.765};for(int i=0;i<ages.Length;i++){int x=i%4*400,y=i/4*400;var pose=ArcheryMotion.At(ages[i],1);ArcheryArt.Bow(g,new PointF(x+10,y+140),347,300,pose);g.DrawString("Load / release: "+ages[i].ToString("F3")+"; flex "+ArcheryArt.BowFlex(pose).ToString("F3"),SystemFonts.DefaultFont,Brushes.White,x+15,y+15);}sheet.Save(Path.Combine(Folder,"bow-load-contact.png"),ImageFormat.Png);}Check(true,"bow loading and spring-back preview saved");
 }
 static void FormationSampling(){using(var image=new Bitmap(900,650))using(var g=Graphics.FromImage(image)){g.SmoothingMode=SmoothingMode.AntiAlias;foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;for(int frame=0;frame<=708;frame++){double age=frame/120.0;var pose=ArcheryMotion.At(age,facing);g.Clear(Color.Transparent);try{ArcheryArt.Bow(g,new PointF(275,260),width,size,pose);}catch(Exception ex){throw new Exception("120 Hz bow / size="+size+" facing="+facing+" age="+age.ToString("R")+" amount="+pose.Bow.ToString("R"),ex);}}Check(true,"120 Hz full bow formation/disappearance renders / "+size+" / "+facing);}
   foreach(int facing in new[]{-1,1}){for(int i=0;i<468;i++){double fire;var frame=AnimationDebugWindow.BowPreview(i/60.0,facing,out fire);g.Clear(Color.Transparent);try{ArcheryArt.Bow(g,new PointF(275,260),347,300,frame.BowPose);}catch(Exception ex){throw new Exception("60 Hz preview frame="+i+" facing="+facing+" poseAge="+frame.BowPose.Age.ToString("R")+" bow="+frame.BowPose.Bow.ToString("R"),ex);}}Check(true,"60 Hz preview fractional poses render / "+facing);}
  }}
 static void Geometry(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;PointF axis=ArcheryMotion.Axis(facing),grip=ArcheryMotion.Grip(width,size,facing),tip=ArcheryArt.BowCurve(grip,axis,size,0),mid=ArcheryArt.BowCurve(grip,axis,size,.5);double depth=(grip.X-tip.X)*axis.X+(grip.Y-tip.Y)*axis.Y;Check(Math.Abs(depth-size*.151234567901235)<.0001&&RigParts.Length(mid,grip)<.0001,"arc apex/string-plane depth is twice old silhouette maximum / "+size+" / "+facing);var pose=new ArcheryPose{Facing=facing};PointF nock=ArcheryMotion.Nock(width,size,pose);double nockDepth=(grip.X-nock.X)*axis.X+(grip.Y-nock.Y)*axis.Y;Check(Math.Abs(nockDepth-ArcheryMotion.BowDepth(size))<.001,"rest nock lies on straight string plane / "+size+" / "+facing);}}
 static void Bounds(){foreach(int size in new[]{220,300,400})foreach(int facing in new[]{-1,1}){int width=PetRenderer.CanvasSize(size).Width;Point origin=new Point(440-width/2,430);int frames=0;for(double age=0;age<=ArcheryMotion.Duration;age+=.1){ArcheryPose pose=ArcheryMotion.At(age,facing);Extent(g=>ArcheryArt.Bow(g,origin,width,size,pose),ArcheryArt.BowBounds(origin,width,size,pose),"bow age="+age);frames++;}Check(true,frames+" bow stages including painted-arrow glow fit the overlay with no clipped pixels / "+size+" / "+facing);
   foreach(Rectangle screen in new[]{new Rectangle(0,0,1200,1000),new Rectangle(500,490,60,60)}){var arrow=new MagicArrow(new PointF(530,520),facing,screen,size);double duration=arrow.FlightTime+MagicArrow.ImpactDuration;int tested=0;for(double age=0;age<duration;age+=.025){var sample=new MagicArrow(arrow.Origin,facing,screen,size);sample.Update(age);Extent(g=>ArcheryArt.Projectile(g,sample),ArcheryArt.ProjectileBounds(sample),"projectile age="+age);tested++;}Check(true,tested+" complete2L-flight/impact frames fit the overlay, including off-canvas tails and short flights / "+size+" / "+facing+" / "+screen.Width);}
  }}
 static void Appearance(){PointF tip=new PointF(650,450),axis=ArcheryMotion.Axis(1);using(var a=Image(g=>ArcheryArt.Arrow(g,tip,axis,ArcheryMotion.ArrowLength(300),300,true,.1)))using(var b=Image(g=>ArcheryArt.Arrow(g,tip,axis,ArcheryMotion.ArrowLength(300),300,true,.2)))using(var repeat=Image(g=>ArcheryArt.Arrow(g,tip,axis,ArcheryMotion.ArrowLength(300),300,true,.1))){Check(Difference(a,b)>250,"helix rotates relative to stationary arrow between frames");Check(Difference(a,repeat)==0,"particles and rotation deterministic at fixed time");int warm=0,translucent=0;foreach(uint p in Array.ConvertAll(PoseMesh.Read(a),v=>(uint)v)){int alpha=(int)(p>>24),red=(int)(p>>16&255),green=(int)(p>>8&255),blue=(int)(p&255);if(alpha>245&&red>=green&&green>blue+5)warm++;if(alpha>=45&&alpha<=180)translucent++;}Console.WriteLine("Core warm pixels="+warm+"; translucent effect pixels="+translucent);a.Save(Path.Combine(Folder,"arrow-effects-sample.png"),ImageFormat.Png);Check(warm>100,"arrow core renders warm white");Check(translucent>350,"thicker helix and white-gold particles retain translucency");}
  var shot=new MagicArrow(new PointF(550,550),1,new Rectangle(0,0,1200,1000),300);shot.Update(.15);using(var b=Image(g=>ArcheryArt.Projectile(g,shot))){PointF origin=shot.Origin;int[] pixels=PoseMesh.Read(b);int ring=0;for(int y=(int)origin.Y-65;y<=origin.Y+65;y++)for(int x=(int)origin.X-65;x<=origin.X+65;x++){double dx=x-origin.X,dy=y-origin.Y;double r=Math.Sqrt(dx*dx+dy*dy);if(r>25&&r<55&&dx+dy>10&&(uint)pixels[y*b.Width+x]>>24>20)ring++;}Check(ring>60,"release burst persists at original arrowhead while projectile flies");}
  foreach(double age in new[]{.5,1.3,2.1})using(var ripples=Image(g=>ArcheryArt.SpiralRipples(g,tip,axis,ArcheryMotion.ArrowLength(300),300,age))){int visible=0;foreach(int pixel in PoseMesh.Read(ripples))if((uint)pixel>>24>8)visible++;Check(age>ArcheryArt.ReleaseRippleDuration&&visible>35,"small helix wavefronts persist after initial release burst / "+age);}
  using(var before=Image(g=>ArcheryArt.SpiralRipples(g,tip,axis,ArcheryMotion.ArrowLength(300),300,.62-1e-6)))using(var after=Image(g=>ArcheryArt.SpiralRipples(g,tip,axis,ArcheryMotion.ArrowLength(300),300,.62+1e-6)))Check(Difference(before,after)<20,"helix ripple cycle wraps without visible popping");
  shot.Update(shot.FlightTime+MagicArrow.RingDuration*.999-shot.Age);Check(Math.Abs(shot.Radius-300*.75*.999)<.001,"screen-edge ring retains three-quarter-height maximum radius");
 }
 static void Preview(){using(var sheet=new Bitmap(2700,2000))using(var g=Graphics.FromImage(sheet)){g.Clear(Color.FromArgb(46,54,66));g.SmoothingMode=SmoothingMode.AntiAlias;double[] times={2.0,2.615,3.3};for(int i=0;i<3;i++){var p=ArcheryMotion.At(times[i],1);ArcheryArt.Bow(g,new PointF(i*900+280,140),347,300,p);g.DrawString("25 degree bow / painted arrow / age "+times[i].ToString("F3"),SystemFonts.DefaultFont,Brushes.White,i*900+18,15);}
   foreach(int facing in new[]{-1,1})for(int i=0;i<3;i++){int row=facing>0?500:1000;ArcheryArt.Arrow(g,new PointF(i*900+(facing>0?740:160),row+165),ArcheryMotion.Axis(facing),ArcheryMotion.ArrowLength(300),300,true,i*.10);g.DrawString((facing>0?"RIGHT":"LEFT")+" / 2-arrow-length spiral / rotating phase "+(i*.10).ToString("F2"),SystemFonts.DefaultFont,Brushes.White,i*900+18,row+15);}
   for(int i=0;i<3;i++){var a=new MagicArrow(new PointF(i*900+510,1740),1,new Rectangle(i*900,1500,900,500),300);a.Update(new[]{.04,.15,.3}[i]);ArcheryArt.Projectile(g,a);g.DrawString("Release burst "+a.Age.ToString("F2"),SystemFonts.DefaultFont,Brushes.White,i*900+18,1515);}sheet.Save(Path.Combine(Folder,"archery-effects-contact.png"),ImageFormat.Png);
  }Check(true,"warm bow, rotating spiral, and release ripple visual preview saved");}
